import TransferHistory from './TransferHistory'
import wooriHomeReference from '../../../src/assets/woori-global-home-reference.png'
import { useRef, useState } from 'react'
import { groups } from './BankingMenu'
import wooriSymbol from '../../../src/assets/woori-financial-symbol.ico'
import './BankingHome.css'
import './GlobalHome.css'

const englishGroups=[
 ['Convenience Services',['Woori WONday Insurance','Woori WON Mobile','Woori WON Wallet','Mobile ID','To the Moon Tickets','Mobile IOU','WON Real Estate','Tax Refund','Rental AI Guardian','Commercial Property AI Guardian','Property Transaction AI Diagnosis','Real Estate AI Guide','WON Arte Gallery','Woori WON Pay','Woori Zero Pay','Silson24']],
 ['Transfers / Withdrawals',['Immediate / Scheduled Transfer','Multiple Transfers','Manage Automatic Transfers','Transfer History','Transfer Management','Split the Bill','ATM / Branch Withdrawal','Mistaken Transfer Refund']],
 ['Account Inquiry / Management',['All Accounts','Closed Accounts','Integrated Account Management','Loan Management','Retirement Pension Management','Housing Subscription Management','Find Dormant Deposits / Insurance','Change Pension Account','Open Banking Management','MyData Management']],
 ['Foreign Currency / Overseas',['Currency Exchange Wallet','Wibee Travel','International Transfer','All Foreign Currency Services','Pre-open an Overseas Account']],
 ['Bills / Taxes',['Pay Bills / Taxes','Bill / Tax Payment History','Register / View Automatic Payments','University Tuition Payment / Inquiry','Court Fee Payment / Inquiry']],
 ['Products',['Deposit / Savings Accounts','Loans','Retirement Pension','Housing Subscription','Funds','Trusts','ISA','Foreign Currency Products','Gold / Silver','Insurance','Sole Proprietors','Yellow Umbrella Mutual Aid','Woori Financial Group']],
 ['Cards',['Explore Woori Cards','Woori Card History / Management','University Student ID Card','Explore Samsung Cards']],
 ['Benefits',['Events','WON PLAY','Earn Free Honey Money','Coupons','eSports','Woori Kids','Woori Teen Teen','Woori Twenties','Woori Office Celeb','Woori Wonder Life','Dedicated Staff Service','TWO CHAIRS','Financial Vouchers']],
 ['Giving / Inclusion',['Donate to Goodwill Store','AI Inclusive Debt Assessment','Good Local Businesses','Donations']],
 ['Certificates / Documents',['Issue Certificates / Public Documents','Electronic Document Wallet','Woori Power of Attorney']],
 ['Branches / ATMs',['Find a Branch / ATM','Restore ATM Limit']],
 ['Banking Support',['Customer Identification (KYC)','Self-certification (FATCA / CRS)','National Housing Bond Purchase / Inquiry','Check Inquiry']],
 ['Customer Support',['Customer Center','Report a Loss','Voice Phishing Prevention','Financial Consumer Information','Sign Language Support']],
] as const

function TransferServiceIcon({index}:{index:number}){
 return <svg className="global-service-art" viewBox="0 0 64 64" fill="none" aria-hidden="true"><defs><linearGradient id={`service-fill-${index}`} x1="5" y1="5" x2="60" y2="60" gradientUnits="userSpaceOnUse"><stop stopColor={['#3cabff','#5ec7d3','#60d7aa','#6a91ff'][index]}/><stop offset="1" stopColor={['#178deb','#00a4b9','#25b18a','#4771ef'][index]}/></linearGradient></defs>{index<2?<><circle cx={index===0?36:32} cy="30" r="25" fill={`url(#service-fill-${index})`}/><path d="M39 18c-8-5-17 0-12 6 2 3 13 2 13 9 0 8-12 10-18 5M32 12v35" transform={index===0?'translate(4 0)':undefined} stroke="white" strokeWidth="4.5" strokeLinecap="round"/>{index===0&&<><path d="M4 40h19M2 46h19M10 52h14" stroke="#3dafff" strokeWidth="3" strokeLinecap="round"/><path d="M5 40h10" stroke="#9bdbff" strokeWidth="2"/></>}</>:index===2?<><rect x="10" y="6" width="44" height="51" rx="9" fill="url(#service-fill-2)"/><rect x="26" y="11" width="12" height="3" rx="1.5" fill="#239e7b"/><circle cx="32" cy="34" r="13" fill="white"/><path d="M23 30a9 9 0 1 0 15 9M27 31h13v11" stroke="#32bd91" strokeWidth="4" strokeLinecap="round" strokeLinejoin="round"/></>:<><rect x="8" y="7" width="48" height="49" rx="10" fill="url(#service-fill-3)"/><path d="M17 22h12M23 16v12M37 22h12M18 37l10 10M28 37 18 47" stroke="white" strokeWidth="4"/><path d="M37 40h12M37 46h12" stroke="#9db5ff" strokeWidth="4"/></>}</svg>
}
function CountryFlag({country}:{country:'us'|'id'|'ph'}){
 return <svg className="global-country-flag" viewBox="0 0 30 30" role="img" aria-label={{us:'United States',id:'Indonesia',ph:'Philippines'}[country]}><defs><clipPath id={`flag-${country}`}><circle cx="15" cy="15" r="14"/></clipPath></defs><g clipPath={`url(#flag-${country})`}><rect width="30" height="30" fill="#fff"/>{country==='us'?<><path d="M0 2h30M0 6h30M0 10h30M0 14h30M0 18h30M0 22h30M0 26h30M0 30h30" stroke="#bc3043" strokeWidth="2"/><rect width="16" height="16" fill="#304678"/><path d="M3 3h1m3 0h1m3 0h1M5 6h1m3 0h1m3 0h1M3 9h1m3 0h1m3 0h1M5 12h1m3 0h1m3 0h1" stroke="white" strokeWidth="1.5"/></>:country==='id'?<rect width="30" height="15" fill="#ef2638"/>:<><rect width="30" height="15" fill="#063eaa"/><rect y="15" width="30" height="15" fill="#df2541"/><path d="m0 0 21 15L0 30z" fill="white"/><circle cx="7" cy="15" r="3" fill="#f6c72c"/><path d="m2 5 1 1m0 18-1 1m14-10h1" stroke="#f6c72c" strokeWidth="2"/></>}</g><circle cx="15" cy="15" r="14" fill="none" stroke="#d9e0e8" strokeWidth=".5"/></svg>
}
function GlobalIcon({kind}:{kind:string}){
 const shapes:Record<string,string>={home:'m3 11 9-8 9 8v10H3zM11 15v6',menu:'M3 5h18M3 12h18M3 19h18',bell:'M5 18h14l-3-5V8a4 4 0 0 0-8 0v5zM10 22h4',inquiry:'M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20M6 10l3 7 3-7 3 7 3-7',transfer:'m8 3 2 4c-8 6-7 14 2 14s10-8 2-14l2-4zM12 10v8M15 11H10q-2 2 2 3t0 3H9',lock:'M5 10h14v12H5zM8 10V6a4 4 0 0 1 8 0v4M12 15v3',location:'M12 22S4 15 4 9a8 8 0 0 1 16 0c0 6-8 13-8 13zM12 6v6',chat:'M3 3h18v14H9l-6 4zM7 9h1m4 0h1m4 0h1'}
 return <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><path d={shapes[kind]||shapes.menu}/></svg>
}

export default function GlobalHome({name,onLogout}:{name:string;onLogout:()=>void}){
 const [menu,setMenu]=useState(false),[notice,setNotice]=useState(''),[query,setQuery]=useState('')
 const scroll=useRef<HTMLDivElement>(null)

 const [historyOpen,setHistoryOpen]=useState(false)
 const select=(title:string)=>{if(title==='Transfer History'||title==='Inquiry'){setHistoryOpen(true);return}if(title==='Woori WONday Insurance')window.parent.postMessage({type:'wonday:open-insurance'},window.location.origin);else setNotice(title)}
 if(historyOpen)return <TransferHistory english onClose={()=>setHistoryOpen(false)}/>
 return <div className="global-home" lang="en">{menu?<>
  <header className="global-menu-header"><button className="global-language" onClick={()=>setNotice('Language · English')}><CountryFlag country="us"/> EN</button><button aria-label="Home" onClick={()=>setMenu(false)}><GlobalIcon kind="home"/></button><button className="global-menu-close" aria-label="Close menu" onClick={()=>setMenu(false)}>×</button></header>
  <div className="global-menu-scroll"><div className="global-menu-account"><button onClick={()=>setNotice('Profile')}>{name}</button><button onClick={onLogout}>Log out ›</button></div><div className="global-menu-quick">{[['lock','Certificate Center'],['location','Branch Locator'],['chat','Customer Service']].map(([icon,title])=><button key={title} onClick={()=>select(title)}><GlobalIcon kind={icon}/><span>{title}</span></button>)}</div><label className="global-menu-search"><span>⌕</span><input aria-label="Search services" placeholder="Search menus and services" value={query} onChange={e=>setQuery(e.target.value)}/></label>
  {groups.map((_group,index)=>{const [title,items]=englishGroups[index];const menuItems:string[]=[...items];if(index===0)menuItems.splice(1,0,'Job Information for Foreign Residents');const matches=menuItems.filter(item=>item.toLowerCase().includes(query.trim().toLowerCase())||title.toLowerCase().includes(query.trim().toLowerCase()));return matches.length?<section className="global-services-section" key={title}><h2><span>{index===0?'✓':index===1?'₩':index===3?'◎':'▧'}</span>{title}</h2>{matches.map(item=><button key={item} className={item==='Woori WONday Insurance'?'global-insurance-link':item==='Job Information for Foreign Residents'?'global-insurance-link global-job-info-link':''} onClick={()=>select(item)}>{item==='Job Information for Foreign Residents'&&<GlobalIcon kind="inquiry"/>}{item==='Woori WONday Insurance'&&<img src={wooriSymbol} alt="Woori"/>}<span>{item}</span>{(item==='Woori WONday Insurance'||item==='Job Information for Foreign Residents')&&<b>›</b>}</button>)}</section>:null})}
  {!('job information for foreign residents'.includes(query.trim().toLowerCase()))&&!englishGroups.some(([title,items])=>title.toLowerCase().includes(query.toLowerCase())||items.some(item=>item.toLowerCase().includes(query.toLowerCase())))&&<p className="global-no-results">No services found.</p>}
  </div></>:<>
  <div className="global-home-scroll" ref={scroll}><section className="global-home-hero"><div className="global-home-greeting"><button onClick={()=>setNotice('Profile')}>{name}, send money with ease</button><button aria-label="Notifications" onClick={()=>select('Notifications')}><GlobalIcon kind="bell"/></button></div><div className="global-original-characters" aria-hidden="true"><img src={wooriHomeReference} alt=""/><div className="global-window-snow">{Array.from({length:12},(_,i)=><i key={i} style={{left:`${7+(i*23)%88}%`,animationDelay:`-${i*.63}s`,animationDuration:`${3.5+(i%4)*.7}s`,width:i%3===0?4:2,height:i%3===0?4:2}}/>)}</div></div><button className="global-transfer-banner" onClick={()=>select('International Transfer')}>Easy and fast, International Transfer <b>›</b></button></section>
  <div className="global-rates" aria-label="Sample exchange rates"><span><CountryFlag country="us"/> USD <b>1,342.8</b></span><span><CountryFlag country="id"/> IDR <b>7.36</b></span><span><CountryFlag country="ph"/> PHP <b>21.11</b></span></div><small className="global-rate-note">Sample rates for preview</small>
  <div className="global-home-tiles">{['Global Quick Transfer','International Transfer','Mobile MoneyGram','Currency Converter'].map((title,i)=><button key={title} onClick={()=>select(title)}><TransferServiceIcon index={i}/><strong>{title}</strong></button>)}</div>
  <button className="global-certificate-banner" onClick={()=>select('Woori WONday Insurance')}><span>Peace of mind for weather-affected working days</span><strong>WONDAY INSURANCE</strong><svg className="global-certificate-shield" viewBox="0 0 90 105" fill="none" aria-hidden="true"><defs><linearGradient id="certificate-metal" x1="0" y1="0" x2="90" y2="105"><stop stopColor="#e5edfa"/><stop offset=".3" stopColor="#96acc9"/><stop offset=".5" stopColor="#fff"/><stop offset=".75" stopColor="#b9cce4"/><stop offset="1" stopColor="#718eb7"/></linearGradient><linearGradient id="certificate-blue" x1="10" y1="15" x2="80" y2="100"><stop stopColor="#61d3ff"/><stop offset=".5" stopColor="#39b0fa"/><stop offset="1" stopColor="#2274e9"/></linearGradient></defs><path d="m45 4 34 10 6 11-4 36c-2 20-18 33-36 41C27 94 11 81 9 61L5 25l6-11z" fill="url(#certificate-metal)"/><path d="m44 10 31 10 4 8-4 32c-2 17-15 29-31 36-16-7-29-19-31-36L9 28l4-8z" fill="url(#certificate-blue)" stroke="#84deff" strokeWidth="2"/><path d="m26 50 13 14 25-26" stroke="#1b7ad4" strokeOpacity=".5" strokeWidth="12" strokeLinecap="round" strokeLinejoin="round" transform="translate(0 3)"/><path d="m26 50 13 14 25-26" stroke="white" strokeWidth="10" strokeLinecap="round" strokeLinejoin="round"/></svg></button>
  </div><nav className="global-home-nav">{[['home','Home'],['inquiry','Inquiry'],['transfer','Transfer'],['menu','Menu']].map(([kind,title])=><button key={title} className={title==='Home'?'active':title==='Menu'?'global-bottom-menu-invite':title==='Inquiry'?'global-inquiry-link':''} onClick={()=>{if(title==='Menu')setMenu(true);else if(title==='Home')scroll.current?.scrollTo({top:0,behavior:'smooth'});else select(title)}}><GlobalIcon kind={kind}/><span>{title}</span></button>)}</nav>
 </>}{notice&&<div className="global-home-notice-shade" onClick={()=>setNotice('')}><section role="dialog" aria-modal="true" aria-label={notice} onClick={e=>e.stopPropagation()}><button className="global-notice-close" aria-label="Close" onClick={()=>setNotice('')}>×</button><h2>{notice}</h2><p>{name}, this is a preview.<br/>No actual banking transactions are connected.</p><button className="global-notice-confirm" autoFocus onClick={()=>setNotice('')}>Confirm</button></section></div>}</div>
}
